// Data for write_int that doesn't depend on output iterator type. It is used to
// avoid template code bloat.
template <typename Char> struct write_int_data {
  size_t size;
  size_t padding;

  FMT_CONSTEXPR write_int_data(int num_digits, unsigned prefix,
                               const format_specs<Char>& specs)
      : size((prefix >> 24) + to_unsigned(num_digits)), padding(0) {
    if (specs.align == align::numeric) {
      auto width = to_unsigned(specs.width);
      if (width > size) {
        padding = width - size;
        size = width;
      }
    } else if (specs.precision > num_digits) {
      size = (prefix >> 24) + to_unsigned(specs.precision);
      padding = to_unsigned(specs.precision - num_digits);
    }
  }
};

// Writes an integer in the format
//   <left-padding><prefix><numeric-padding><digits><right-padding>
// where <digits> are written by write_digits(it).
// prefix contains chars in three lower bytes and the size in the fourth byte.
template <typename OutputIt, typename Char, typename W>
FMT_CONSTEXPR FMT_INLINE auto write_int(OutputIt out, int num_digits,
                                        unsigned prefix,
                                        const format_specs<Char>& specs,
                                        W write_digits) -> OutputIt {
  // Slightly faster check for specs.width == 0 && specs.precision == -1.
  if ((specs.width | (specs.precision + 1)) == 0) {
    auto it = reserve(out, to_unsigned(num_digits) + (prefix >> 24));
    if (prefix != 0) {
      for (unsigned p = prefix & 0xffffff; p != 0; p >>= 8)
        *it++ = static_cast<Char>(p & 0xff);
    }
    return base_iterator(out, write_digits(it));
  }
  auto data = write_int_data<Char>(num_digits, prefix, specs);
  return write_padded<align::right>(
      out, specs, data.size, [=](reserve_iterator<OutputIt> it) {
        for (unsigned p = prefix & 0xffffff; p != 0; p >>= 8)
          *it++ = static_cast<Char>(p & 0xff);
        it = detail::fill_n(it, data.padding, static_cast<Char>('0'));
        return write_digits(it);
      });
}

template <typename Char> class digit_grouping {
 private:
  std::string grouping_;
  std::basic_string<Char> thousands_sep_;

  struct next_state {
    std::string::const_iterator group;
    int pos;
  };
  next_state initial_state() const { return {grouping_.begin(), 0}; }

  // Returns the next digit group separator position.
  int next(next_state& state) const {
    if (thousands_sep_.empty()) return max_value<int>();
    if (state.group == grouping_.end()) return state.pos += grouping_.back();
    if (*state.group <= 0 || *state.group == max_value<char>())
      return max_value<int>();
    state.pos += *state.group++;
    return state.pos;
  }

 public:
  explicit digit_grouping(locale_ref loc, bool localized = true) {
    if (!localized) return;
    auto sep = thousands_sep<Char>(loc);
    grouping_ = sep.grouping;
    if (sep.thousands_sep) thousands_sep_.assign(1, sep.thousands_sep);
  }
  digit_grouping(std::string grouping, std::basic_string<Char> sep)
      : grouping_(std::move(grouping)), thousands_sep_(std::move(sep)) {}

  bool has_separator() const { return !thousands_sep_.empty(); }

  auto grouping() const -> const std::string& { return grouping_; }
  auto separator() const -> const std::basic_string<Char>& {
    return thousands_sep_;
  }

  int count_separators(int num_digits) const {
    int count = 0;
    auto state = initial_state();
    while (num_digits > next(state)) ++count;
    return count;
  }

  // Applies grouping to digits and write the output to out.
  template <typename Out, typename C>
  Out apply(Out out, basic_string_view<C> digits) const {
    auto num_digits = static_cast<int>(digits.size());
    auto separators = basic_memory_buffer<int>();
    separators.push_back(0);
    auto state = initial_state();
    while (int i = next(state)) {
      if (i >= num_digits) break;
      separators.push_back(i);
    }
    for (int i = 0, sep_index = static_cast<int>(separators.size() - 1);
         i < num_digits; ++i) {
      if (num_digits - i == separators[sep_index]) {
        out =
            copy_str<Char>(thousands_sep_.data(),
                           thousands_sep_.data() + thousands_sep_.size(), out);
        --sep_index;
      }
      *out++ = static_cast<Char>(digits[to_unsigned(i)]);
    }
    return out;
  }
};

// Writes a decimal integer with digit grouping.
template <typename OutputIt, typename UInt, typename Char>
auto write_int(OutputIt out, UInt value, unsigned prefix,
               const format_specs<Char>& specs,
               const digit_grouping<Char>& grouping) -> OutputIt {
  static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");

  int num_digits = 1;
  {
    auto counted = value;
    for (;;) {
      if (counted < 10) break;
      if (counted < 100) {
        num_digits += 1;
        break;
      }
      if (counted < 1000) {
        num_digits += 2;
        break;
      }
      if (counted < 10000) {
        num_digits += 3;
        break;
      }
      counted /= 10000u;
      num_digits += 4;
    }
  }

  char digits[40];
  {
    char* ptr = digits + num_digits;
    auto formatted = value;
    while (formatted >= 100) {
      ptr -= 2;
      const char* pair = digits2(static_cast<size_t>(formatted % 100));
      ptr[0] = pair[0];
      ptr[1] = pair[1];
      formatted /= 100;
    }
    if (formatted < 10) {
      *--ptr = static_cast<char>('0' + formatted);
    } else {
      ptr -= 2;
      const char* pair = digits2(static_cast<size_t>(formatted));
      ptr[0] = pair[0];
      ptr[1] = pair[1];
    }
  }

  const char* digit_data = digits;
  int digit_count = num_digits;
  const std::string& grouping_pattern = grouping.grouping();
  const std::basic_string<Char>& thousands_sep = grouping.separator();
  int separator_count = grouping.count_separators(digit_count);
  unsigned prefix_size = prefix != 0 ? 1u : 0u;
  unsigned size =
      prefix_size + to_unsigned(digit_count) + to_unsigned(separator_count);

  unsigned spec_width = to_unsigned(specs.width);
  size_t width = size;
  size_t padding = spec_width > width ? spec_width - width : 0;
  const char* shifts = "\x00\x1f\x00\x01";
  size_t left_padding = padding >> shifts[specs.align];
  size_t right_padding = padding - left_padding;
  auto it = reserve(out, size + padding * specs.fill.size());

  if (left_padding != 0) {
    size_t fill_size = specs.fill.size();
    if (fill_size == 1) {
      for (size_t i = 0; i < left_padding; ++i) {
        it = copy_str<Char>(specs.fill.data(), specs.fill.data() + 1, it);
      }
    } else if (fill_size > 1) {
      const Char* fill_data = specs.fill.data();
      for (size_t i = 0; i < left_padding; ++i) {
        const Char* begin = fill_data;
        const Char* end = fill_data + fill_size;
        while (begin != end) {
          it = copy_str<Char>(begin, begin + 1, it);
          ++begin;
        }
      }
    }
  }

  if (prefix != 0) {
    char sign = static_cast<char>(prefix);
    *it++ = static_cast<Char>(sign);
  }

  if (digit_count > 0) {
    int seps[40];
    int sep_len = 0;
    seps[sep_len++] = 0;
    if (!thousands_sep.empty()) {
      auto group = grouping_pattern.begin();
      int pos = 0;
      for (;;) {
        int next_pos = 0;
        if (group == grouping_pattern.end()) {
          pos += grouping_pattern.back();
          next_pos = pos;
        } else if (*group <= 0 || *group == max_value<char>()) {
          next_pos = max_value<int>();
        } else {
          pos += *group++;
          next_pos = pos;
        }
        if (next_pos == 0) break;
        if (next_pos >= digit_count) break;
        if (sep_len < 40) {
          seps[sep_len++] = next_pos;
        } else {
          break;
        }
      }
    }
    int sep_index = sep_len - 1;
    for (int i = 0; i < digit_count; ++i) {
      if (sep_index >= 0) {
        if (digit_count - i == seps[sep_index]) {
          if (thousands_sep.size() == 1) {
            it = copy_str<Char>(thousands_sep.data(),
                                thousands_sep.data() + 1, it);
          } else if (thousands_sep.size() > 1) {
            const Char* begin = thousands_sep.data();
            const Char* end = begin + thousands_sep.size();
            while (begin != end) {
              it = copy_str<Char>(begin, begin + 1, it);
              ++begin;
            }
          }
          --sep_index;
        }
      }
      *it++ = static_cast<Char>(digit_data[to_unsigned(i)]);
    }
  }

  if (right_padding != 0) {
    size_t fill_size = specs.fill.size();
    if (fill_size == 1) {
      for (size_t i = 0; i < right_padding; ++i) {
        it = copy_str<Char>(specs.fill.data(), specs.fill.data() + 1, it);
      }
    } else if (fill_size > 1) {
      const Char* fill_data = specs.fill.data();
      for (size_t i = 0; i < right_padding; ++i) {
        const Char* begin = fill_data;
        const Char* end = fill_data + fill_size;
        while (begin != end) {
          it = copy_str<Char>(begin, begin + 1, it);
          ++begin;
        }
      }
    }
  }

  return base_iterator(out, it);

